const API_BASE_PATH = "/api";

export { customFetch } from "./custom-fetch";

export const apiClient = {
  // 1. እቃዎችን ማምጫ
  getProducts: async () => {
    const res = await fetch(`${API_BASE_PATH}/products`);
    return res.json();
  },

  // 2. አዲስ እቃ መደርደሪያ ላይ መጫኛ
  createProduct: async (data: any) => {
    const res = await fetch(`${API_BASE_PATH}/products`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    return res.json();
  },

  // 3. ሱቅ መመዝገቢያ
  registerShop: async (data: any) => {
    const res = await fetch(`${API_BASE_PATH}/shops/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    return res.json();
  },

  // 4. ክፍያ ማስፈጸሚያ (Escrow Checkout)
  processPayment: async (data: any) => {
    const res = await fetch(`${API_BASE_PATH}/checkout/pay`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    return res.json();
  },
};
export * from './generated/api';
export * from './generated/api.schemas';
